uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.0 .. 1.0 = 0.2;
uniform float intensity : 0.0 .. 2.0 = 1.0;
uniform vec3 emberColor : color = 0.8, 0.2, 0.0;
uniform vec3 sparkColor : color = 0.9, 0.9, 0.9;
uniform float sparkChance : 0.0 .. 0.02 = 0.005;
uniform float sparkSize : 0.0 .. 0.5 = 0.12;

state fixed ph;
state fixed drift;

void update() {
  ph = fract(ph + fixed(dt * speed * 0.5));
  drift = drift + fixed(dt * speed * 0.05);
}

vec3 shade(Led led) {
  fixed uv_x = fixed(led.uv.x);
  fixed uv_y = fixed(led.uv.y);
  fixed s = fixed(led.s);

  // ember glow: vertical band with wave
  fixed band = clamp((uv_y - fixed(0.5)) * fixed(2.0), fixed(-1.0), fixed(1.0));
  fixed wave = sin(fixed(uv_x) * fixed(3.0) + ph) * fixed(0.2);
  fixed ember = band * wave;

  // occasional sparks: random per-LED based on frame and index
  fixed rnd = hash(fixed(led.idx) * fixed(7.0) + drift) * fixed(1.0);
  if (rnd < sparkChance) {
    fixed spark = step(s, sparkSize) * (fixed(1.0) - (s * fixed(0.2)));
    return sparkColor * spark;
  }

  // combine
  fixed final = clamp(ember * intensity + fixed(0.1), fixed(0.0), fixed(1.0)) * fixed(1.0);
  return emberColor * final;
}
